<section class="blade-panel" x-data="{ orders: [], page: 1, last: 1, error: '', async load(number = 1) { try { const r = await fetch('/admin/dashboard/orders?page=' + number, {headers:{Accept:'application/json'}}); if (!r.ok) throw new Error('No se pudieron cargar los pedidos.'); const d = await r.json(); this.orders = d.data; this.page = d.current_page; this.last = d.last_page; } catch(e) { this.error = e.message; } } }" x-init="load()"><h1>Pedidos y pre-pedidos</h1><p role="alert" x-text="error"></p><div class="blade-table-wrap"><table class="blade-table"><thead><tr><th>Folio</th><th>Correo</th><th>Estado</th><th>Moneda</th><th>Total</th></tr></thead><tbody><template x-for="order in orders" :key="order.id"><tr><td x-text="order.order_number"></td><td x-text="order.customer_email"></td><td x-text="order.status"></td><td x-text="order.currency"></td><td x-text="order.grand_total"></td></tr></template></tbody></table></div><p x-show="!orders.length">Sin pedidos.</p><button type="button" :disabled="page <= 1" @click="load(page-1)">Anterior</button><span x-text="page + ' / ' + last"></span><button type="button" :disabled="page >= last" @click="load(page+1)">Siguiente</button></section>